<?php
declare(strict_types=1);
use App\Service\{DailyReportService,FloorStatusService,OperationsProfile,OrderService,StaffReservationService,BillingService,BookingClock};
if(!class_exists(DailyReportService::class)||!class_exists(FloorStatusService::class)){fwrite(STDERR,"FAIL missing read-only B6 report/floor services\n");exit(1);}
function oActor($t):array{$q=$t->pdo->query("SELECT * FROM users WHERE email='b4-admin@lumina.test'");$u=$q->fetch();return $u?['id'=>(int)$u['id'],'stamp'=>App\Core\StaffAccess::stamp($u)]:b4actor($t);}
function oBook($t,string $category='bv_family',int $party=5,int $food=200000):array{
 $mid=(int)$t->pdo->query('SELECT m.id FROM menu_items m JOIN menu_categories c ON c.id=m.category_id WHERE m.is_available=1 AND c.is_active=1 ORDER BY m.price_cents LIMIT 1')->fetchColumn();$t->pdo->prepare('UPDATE menu_items SET price_cents=10000 WHERE id=?')->execute([$mid]);return b4book($t,$category,$party,$food);
}
function oSeat($t,array $b):int{(new StaffReservationService($t->pdo,b4clock($t,'10:00:00')))->transition(oActor($t),$b['r']['code'],1,'seat','Isolated operational arrival');return (int)$t->pdo->query('SELECT id FROM orders ORDER BY id DESC LIMIT 1')->fetchColumn();}
function oAct($t,int $id,string $action):array{$s=new OrderService($t->pdo,b4clock($t,'10:01:00'));$q=$t->pdo->prepare('SELECT version FROM orders WHERE id=?');$q->execute([$id]);return $s->mutate(oActor($t),$id,(int)$q->fetchColumn(),$action,bin2hex(random_bytes(4)).'-1111-1111-1111-'.bin2hex(random_bytes(6)),[])['order'];}
function oMeal($t,array $b):void{$id=oSeat($t,$b);foreach(['start','ready','serve','close'] as $action)oAct($t,$id,$action);}
function oFinal($t,array $b):void{$a=oActor($t);$id=(int)$b['r']['id'];$q=(new BillingService($t->pdo,new BookingClock($t->pdo)))->quote($a,$id);if($q['due_cents'])pmoney($t,$a,$id,'payment',$q['due_cents']);pmoney($t,$a,$id,'finalize');}
function oReport($t,?string $day=null):array{return (new DailyReportService($t->pdo,new BookingClock($t->pdo)))->daily(oActor($t),$day??$t->date);}
function oFloor($t,string $when):array{return (new FloorStatusService($t->pdo,new BookingClock($t->pdo)))->snapshot($when);}
function oTable($t,array $b,array $floor):array{$q=$t->pdo->prepare('SELECT table_id FROM reservation_tables WHERE reservation_id=? LIMIT 1');$q->execute([$b['r']['id']]);$id=(int)$q->fetchColumn();return array_values(array_filter($floor,fn($x)=>$x['id']===$id))[0];}
if(defined('OPERATIONS_FIXTURE_ONLY'))return;
$t->test('B6 empty report is zero and does not create financial records',function($t){$r=oReport($t);$t->assert($r['reservations']['total']===0&&$r['food']['finalized_cents']===0&&$r['transactions']['net_cents']===0&&$t->count('billing_accounts')===0);});
$t->test('B6 scheduled food and received base are not finalized food sales',function($t){$b=oBook($t);pmoney($t,oActor($t),(int)$b['r']['id'],'advance',50000);$r=oReport($t);$t->assert($r['food']['finalized_cents']===0&&$r['food']['unfinalized_ordered_cents']===0&&$r['reservations']['confirmed']===1);});
$t->test('B6 served and closed food is unfinalized until cashier closure',function($t){$b=oBook($t);oMeal($t,$b);$r=oReport($t);$t->assert($r['food']['finalized_cents']===0&&$r['food']['unfinalized_ordered_cents']===200000);oFinal($t,$b);$r=oReport($t);$t->assert($r['food']['finalized_cents']===200000&&$r['food']['unfinalized_ordered_cents']===0&&$r['rows'][0]['due_cents']===0);});
$t->test('B6 multiple lines and split receipts do not multiply sales or credit',function($t){$b=oBook($t);$a=oActor($t);$id=(int)$b['r']['id'];pmoney($t,$a,$id,'advance',20000);pmoney($t,$a,$id,'advance',30000);oMeal($t,$b);$t->pdo->exec('UPDATE order_items SET qty=10');$t->pdo->exec("INSERT INTO order_items(order_id,menu_item_id,qty,unit_price_cents,status) SELECT order_id,menu_item_id,10,unit_price_cents,'served' FROM order_items LIMIT 1");pmoney($t,$a,$id,'payment',100000);pmoney($t,$a,$id,'payment',50000);oFinal($t,$b);$t->pdo->exec("UPDATE billing_events SET created_at='".$t->date." 12:00:00'");$r=oReport($t);$t->assert($r['food']['finalized_cents']===200000&&$r['food']['credit_applied_cents']===50000&&$r['transactions']['received_cents']===200000);});
$t->test('B6 prior-day advance and current food use separate named date bases',function($t){$b=oBook($t);$id=(int)$b['r']['id'];pmoney($t,oActor($t),$id,'advance',50000);oMeal($t,$b);oFinal($t,$b);$prior=(new DateTimeImmutable($t->date))->modify('-1 day')->format('Y-m-d');$t->pdo->exec("UPDATE billing_events SET created_at='".$t->date." 12:00:00'");$t->pdo->exec("UPDATE billing_events SET created_at='$prior 23:59:59' WHERE kind='advance'");$r=oReport($t);$old=oReport($t,$prior);$t->assert($r['food']['finalized_cents']===200000&&$r['transactions']['received_cents']===150000&&$old['food']['finalized_cents']===0&&$old['transactions']['advance_cents']===50000);});
$t->test('B6 VIP extras and cancellation retention stay separate from food sales',function($t){$b=oBook($t,'bv_vip',16,250000);$id=(int)$b['r']['id'];$a=oActor($t);pmoney($t,$a,$id,'advance',250000);pmoney($t,$a,$id,'extra_receipt',30000);pcancel($t,$b,$t->date.' 09:00:00');pmoney($t,$a,$id,'review_cancellation');pmoney($t,$a,$id,'refund_extra',30000);pmoney($t,$a,$id,'finalize');$t->pdo->exec("UPDATE billing_events SET created_at='".$t->date." 09:01:00'");$t->pdo->exec("UPDATE policy_money_events SET created_at='".$t->date." 09:02:00'");$r=oReport($t);$t->assert($r['food']['finalized_cents']===0&&$r['retained_cents']===250000&&$r['transactions']['extra_receipt_cents']===30000&&$r['transactions']['refunded_cents']===30000&&$r['transactions']['net_cents']===250000);});
$t->test('B6 later actual refund affects transaction date rather than food date',function($t){$b=oBook($t);$id=(int)$b['r']['id'];$a=oActor($t);pmoney($t,$a,$id,'advance',50000);pcancel($t,$b,(new DateTimeImmutable($t->date))->modify('-2 days')->format('Y-m-d').' 09:00:00');pmoney($t,$a,$id,'review_cancellation');pmoney($t,$a,$id,'refund_base',50000);$next=(new DateTimeImmutable($t->date))->modify('+1 day')->format('Y-m-d');$t->pdo->exec("UPDATE billing_events SET created_at='".$t->date." 23:59:59'");$t->pdo->exec("UPDATE policy_money_events SET created_at='$next 00:00:00'");$r=oReport($t);$later=oReport($t,$next);$t->assert($r['transactions']['received_cents']===50000&&$r['transactions']['refunded_cents']===0&&$later['transactions']['net_cents']===-50000);});
$t->test('B6 invalid date and nonfinancial roles cannot read reports',function($t){$s=new DailyReportService($t->pdo,new BookingClock($t->pdo));$t->expectError('invalid_date',fn()=>$s->daily(oActor($t),'2026-02-30'));$roles=['host','server','kitchen'];foreach($roles as $role){$rid=(int)$t->pdo->query("SELECT id FROM roles WHERE code='$role'")->fetchColumn();$a=oActor($t);$t->pdo->prepare('UPDATE users SET role_id=? WHERE id=?')->execute([$rid,$a['id']]);$u=$t->pdo->query('SELECT * FROM users WHERE id='.(int)$a['id'])->fetch();$actor=['id'=>$a['id'],'stamp'=>App\Core\StaffAccess::stamp($u)];$t->expectError('staff_forbidden',fn()=>$s->daily($actor,$t->date));$t->pdo->prepare("UPDATE users SET role_id=(SELECT id FROM roles WHERE code='admin') WHERE id=?")->execute([$a['id']]);}});
$t->test('B6 final financial history cannot be erased through staff delete',function($t){$b=oBook($t);oMeal($t,$b);oFinal($t,$b);$s=new StaffReservationService($t->pdo,new BookingClock($t->pdo));$r=$s->row($b['r']['code']);$t->expectError('booking_has_billing',fn()=>$s->delete(oActor($t),$r['code'],(int)$r['version']));$t->assert(oReport($t)['food']['finalized_cents']===200000);});
$t->test('B6 available and reserved floor states use active nine units',function($t){$t->assert(count(oFloor($t,$t->date.' 09:00:00'))===9);$b=oBook($t);$t->assert(oTable($t,$b,oFloor($t,$t->date.' 09:59:59'))['state']==='available'&&oTable($t,$b,oFloor($t,$t->date.' 10:00:00'))['state']==='reserved');});
$t->test('B6 occupied overrun remains occupied across midnight',function($t){$b=oBook($t);oSeat($t,$b);$next=(new DateTimeImmutable($t->date))->modify('+1 day')->format('Y-m-d');$t->assert(oTable($t,$b,oFloor($t,$next.' 00:00:00'))['state']==='occupied');});
$t->test('B6 actual completion produces cleanup through exactly15min half-open',function($t){$b=oBook($t);oMeal($t,$b);$s=new StaffReservationService($t->pdo,b4clock($t,'12:00:30'));$r=$s->row($b['r']['code']);$s->transition(oActor($t),$r['code'],(int)$r['version'],'complete','Meal complete');$t->assert(oTable($t,$b,oFloor($t,$t->date.' 12:00:30'))['state']==='clean_up'&&oTable($t,$b,oFloor($t,$t->date.' 12:15:29'))['state']==='clean_up'&&oTable($t,$b,oFloor($t,$t->date.' 12:15:30'))['state']==='available');});
$t->test('B6 manual closure is unavailable rather than invented cleanup',function($t){$b=oBook($t);pcancel($t,$b,$t->date.' 09:00:00');$id=(int)$t->pdo->query('SELECT table_id FROM reservation_tables LIMIT 1')->fetchColumn();$t->pdo->prepare("INSERT INTO blackout_dates(scope,scope_id,starts_at,ends_at,reason) VALUES('table',?,?,?,'Table reset after unrelated manual closure')")->execute([$id,$t->date.' 10:00:00',$t->date.' 10:15:00']);$t->assert(oTable($t,$b,oFloor($t,$t->date.' 10:00:00'))['state']==='blocked');});
$t->test('B6 temporary checkout hold is not a confirmed reservation',function($t){$h=b4hold($t);$f=oFloor($t,$t->date.' 10:00:00');$t->assert(count(array_filter($f,fn($r)=>$r['state']==='held'))===1&&$t->count('reservations')===0);});
$t->test('B6 finalized VIP base credit and extras are not added to food twice',function($t){$b=oBook($t,'bv_vip',16,250000);$id=(int)$b['r']['id'];$a=oActor($t);pmoney($t,$a,$id,'advance',250000);pmoney($t,$a,$id,'extra_receipt',30000);oMeal($t,$b);oFinal($t,$b);$r=oReport($t);$t->assert($r['food']['finalized_cents']===250000&&$r['food']['credit_applied_cents']===250000&&$r['food']['extras_assessed_cents']===30000&&$r['rows'][0]['received_cents']===280000);});
$t->test('B6 void lines and void rounds are excluded from finalized food',function($t){$b=oBook($t);oMeal($t,$b);$mid=(int)$t->pdo->query('SELECT menu_item_id FROM order_items LIMIT 1')->fetchColumn();$oid=(int)$t->pdo->query('SELECT id FROM orders LIMIT 1')->fetchColumn();$t->pdo->prepare("INSERT INTO order_items(order_id,menu_item_id,qty,unit_price_cents,status) VALUES (?,?,1,99999,'void')")->execute([$oid,$mid]);$tid=(int)$t->pdo->query('SELECT table_id FROM orders LIMIT 1')->fetchColumn();$t->pdo->prepare("INSERT INTO orders(reservation_id,table_id,status) VALUES (?,?,'void')")->execute([$b['r']['id'],$tid]);$void=(int)$t->pdo->lastInsertId();$t->pdo->prepare("INSERT INTO order_items(order_id,menu_item_id,qty,unit_price_cents,status) VALUES (?,?,1,88888,'served')")->execute([$void,$mid]);oFinal($t,$b);$t->assert(oReport($t)['food']['finalized_cents']===200000);});
$t->test('B6 cash and external-card transaction methods reconcile separately',function($t){$b=oBook($t);$a=oActor($t);$id=(int)$b['r']['id'];pmoney($t,$a,$id,'advance',50000);oMeal($t,$b);$s=new BillingService($t->pdo,new BookingClock($t->pdo));$q=$s->quote($a,$id);$s->mutate($a,$id,'payment',$q['revision'],'44444444-4444-4444-4444-444444444444',['amount_cents'=>150000,'method'=>'external_card','reason'=>'Actual external card rehearsal']);oFinal($t,$b);$t->pdo->exec("UPDATE billing_events SET created_at='".$t->date." 12:00:00'");$r=oReport($t);$t->assert($r['methods']['cash']['net_cents']===50000&&$r['methods']['external_card']['net_cents']===150000);});
$t->test('B6 report reads are bounded and never alter ledgers',function($t){$b=oBook($t);oMeal($t,$b);oFinal($t,$b);$a=oActor($t);$sql='SELECT id,final_snapshot FROM billing_accounts ORDER BY id';$before=$t->pdo->query($sql)->fetchAll();$events=$t->count('billing_events');$reads=(int)$t->pdo->query("SHOW SESSION STATUS LIKE 'Com_select'")->fetch(PDO::FETCH_NUM)[1];(new DailyReportService($t->pdo,new BookingClock($t->pdo)))->daily($a,$t->date);$after=(int)$t->pdo->query("SHOW SESSION STATUS LIKE 'Com_select'")->fetch(PDO::FETCH_NUM)[1];$t->assert($after-$reads<=14&&$before===$t->pdo->query($sql)->fetchAll()&&$events===$t->count('billing_events'));});
$t->test('B6 corrupted finalized snapshot fails rather than inventing reconciled sales',function($t){$b=oBook($t);oMeal($t,$b);oFinal($t,$b);$t->pdo->exec("UPDATE billing_accounts SET final_snapshot=JSON_SET(final_snapshot,'$.food_cents',1)");$t->expectError('report_conflict',fn()=>oReport($t));});
$t->test('B6 expired checkout hold is Available without becoming a booking',function($t){b4hold($t);$t->pdo->exec("UPDATE holds SET expires_at=DATE_SUB(NOW(),INTERVAL 1 SECOND)");$t->assert(count(array_filter(oFloor($t,$t->date.' 10:00:00'),fn($r)=>$r['state']==='held'))===0&&$t->count('reservations')===0);});
$t->test('B6 cancellation releases a table without inventing cleanup or food sales',function($t){$b=oBook($t);pcancel($t,$b,$t->date.' 09:00:00');$t->assert(oTable($t,$b,oFloor($t,$t->date.' 10:00:00'))['state']==='available'&&oReport($t)['food']['finalized_cents']===0);});
$t->finish();
